  border-bottom: 1px solid #e2e8f0;
}

.section-body {
  font-size: 11px;
  color: #334155;
  padding: 2px 0 6px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.info-grid.two-columns {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 8px;
}

.info-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.info-card table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.info-card td {
  padding: 2px 0;
  vertical-align: top;
  line-height: 1.4;
}

.info-card .label {
  width: 42%;
  color: #64748b;
  white-space: nowrap;
}

.info-card .value {
  text-align: left;
  font-weight: 600;
  color: #111827;
  word-break: break-word;
}

.inspection-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.inspection-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.inspection-title {
  font-weight: 600;
  margin-bottom: 6px;
  color: #0f172a;
}

.inspection-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.inspection-list li {
  padding: 2px 0;
}

.inspection-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.inspection-note {
  font-size: 10px;
  color: #64748b;
  padding-left: 2px;
}

.status {
  font-weight: 600;
}

.status.ok {
  color: #059669;
}

.status.need-attention {
  color: #d97706;
}

.status.replace {
  color: #dc2626;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 8px;
}

.parts-list {
  margin: 0;
  padding-left: 16px;
  color: #334155;
}

.signature-page {
  page-break-before: always;
  margin-top: 16px;
}

.signature-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  margin-top: 12px;
}

.signature-title {
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 24px;
}

.signature-line {
  border-bottom: 1px solid #94a3b8;
  margin-bottom: 8px;
}

.signature-fields {
  font-size: 10px;
  color: #64748b;
  display: grid;
  gap: 4px;
}

.signature-label {
  color: #475569;
}

.signature-footer {
  text-align: center;
  font-size: 10px;
  color: #64748b;
  border-top: 1px solid #e2e8f0;
  padding-top: 8px;
  margin-top: 16px;
}

